#include <print>

int main() {
    int* arr = new int[10];
    for (int i = 0; i < 10; ++i)
        arr[i] = i + 1;

    int sum = 0;
    for (int i = 0; i < 10; ++i)
        sum += arr[i];
    std::println("和 = {}", sum);

    delete[] arr;
    arr = nullptr;
    // delete[] arr;        刚才把这行注释掉跑了一遍：屏幕上一行不缺，那块地却没还
    // 栈只有几 MB，一百万个 int 是 4 MB 左右，硬放会堆栈溢出当场崩；堆是仓库，大小运行时才定也行
    return 0;
}

